import argparse
import logging
import sys

from zephyrapi import ZephyrApp

app = ZephyrApp()


@app.get("/")
def read_root():
    # Simple JSON greeting
    return {"Hello": "World"}


@app.get("/items/{item_id}")
def read_item(item_id: int, q: str | None = None):
    return {"item_id": item_id, "q": q}


def build_parser():
    parser = argparse.ArgumentParser(description="Small items API")
    parser.add_argument("--port", type=int, default=8000)
    return parser


def main(argv=None):
    logging.basicConfig(level=logging.INFO)
    args = build_parser().parse_args(argv)
    logging.info("Starting API on port %d", args.port)
    app.serve(port=args.port)
    return 0


if __name__ == "__main__":
    sys.exit(main())

